def lire_ligne(ligne):
    code, titre, places = ligne
    return {"code": code, "titre": titre, "places": places}

def programme(activites):
    resultat = []
    for rang, activite in enumerate(activites, start=1):
        titre, minutes = activite
        resultat.append({
            "rang": rang,
            "titre": titre,
            "heures": minutes // 60,
            "minutes": minutes % 60,
        })
    return resultat
